            print(f'{ts} USER-TEXT: {brief(content)}')
        elif isinstance(content, list):
            for c in content:
                if isinstance(c, dict):
                    ctype = c.get('type')
                    if ctype == 'text':
                        print(f'{ts} USER-TEXT: {brief(c.get(\"text\"))}')
